import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.CxkNbRKf.js";const g=JSON.parse('{"title":"Upgrade from 5.6 to 5.7 and later","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/upgrade/upgrade-57.md","filePath":"installation-guide/upgrade/upgrade-57.md","lastUpdated":1794965376000}'),s={name:"installation-guide/upgrade/upgrade-57.md"};function n(r,e,d,l,h,c){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="upgrade-from-5-6-to-5-7-and-later" tabindex="-1">Upgrade from 5.6 to 5.7 and later <a class="header-anchor" href="#upgrade-from-5-6-to-5-7-and-later" aria-label="Permalink to &quot;Upgrade from 5.6 to 5.7 and later&quot;">​</a></h1><p>Use this guide to upgrade NADA <strong>5.6</strong> or any <strong>5.7.x</strong> release to <strong>5.7</strong>, <strong>5.8</strong> or a later release. The steps are the same for every release from 5.6 onward, so you do not need to upgrade through each release in between: one run of the database migrations brings the database up to date.</p><p>If your catalog runs a release older than 5.6, first follow <a href="/nada-documentation/installation-guide/upgrade/upgrade-56.html">Upgrade to 5.6</a>.</p><div class="tip custom-block"><p class="custom-block-title">AI search and MCP</p><p>AI search and the MCP server for AI assistants need <strong>NADA 5.8</strong> or later. Upgrade NADA first, then follow <a href="#after-the-upgrade-new-components">After the upgrade: new components</a>.</p></div><h2 id="how-database-upgrades-work" tabindex="-1">How database upgrades work <a class="header-anchor" href="#how-database-upgrades-work" aria-label="Permalink to &quot;How database upgrades work&quot;">​</a></h2><p>Database changes are applied by migrations in <code>application/migrations/</code>. The database records the latest migration it has applied, and <code>migrate latest</code> runs every newer one in order.</p><ul><li>Every migration is <strong>idempotent</strong>. If one fails part way, fix the cause and run <code>migrate latest</code> again; steps already applied are skipped.</li><li>Migrations are <strong>one-way</strong>. There is no rollback, so restore your backup if you need to go back.</li></ul><p>For the CLI commands and troubleshooting, see <a href="/nada-documentation/installation-guide/database-migrations-cli.html">Database migrations (CLI)</a>.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>[ ] Back up the <strong>database</strong> (full backup).</li><li>[ ] Back up the NADA folder, especially <code>application/config/</code>, <code>datafiles/</code>, <code>files/</code> and your theme folder under <code>themes/</code>.</li><li>[ ] Test the upgrade on a copy of the site first, if you can.</li><li>[ ] Note your current version: open <strong>Site administration</strong>, or check the release you deployed.</li></ul><h2 id="_1-deploy-the-new-code" tabindex="-1">1. Deploy the new code <a class="header-anchor" href="#_1-deploy-the-new-code" aria-label="Permalink to &quot;1. Deploy the new code&quot;">​</a></h2><p>Replace the application files with the new release, from the <a href="https://github.com/ihsn/nada/releases" target="_blank" rel="noreferrer">release zip</a> or with Git:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/nada</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tags</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v5.8</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # use the release you are upgrading to</span></span></code></pre></div><h3 id="configuration-files" tabindex="-1">Configuration files <a class="header-anchor" href="#configuration-files" aria-label="Permalink to &quot;Configuration files&quot;">​</a></h3><p>These files hold your site&#39;s settings and are not part of the release. A release zip or <code>git checkout</code> leaves them in place:</p><table tabindex="0"><thead><tr><th>File</th><th>Contents</th></tr></thead><tbody><tr><td><code>application/config/database.php</code></td><td>Database connection</td></tr><tr><td><code>application/config/email.php</code></td><td>Email settings</td></tr><tr><td><code>application/config/auth.local.php</code></td><td>Email credentials, OAuth and other secrets</td></tr><tr><td><code>application/config/mongo.php</code></td><td>MongoDB connection (indicators)</td></tr></tbody></table><p>The other files in <code>application/config/</code> are part of the release and are replaced with the new versions. If you edited any of them (for example <code>config.php</code>, <code>solr.php</code> or <code>rest.php</code>), copy your changes into the new files rather than restoring the old files. An old file keeps the site from getting the release&#39;s changes.</p><div class="warning custom-block"><p class="custom-block-title">Upgrading from 5.6 with MongoDB</p><p>In 5.6, <code>application/config/mongo.php</code> was part of the release. From 5.7.2 it is a local file, and the release ships <code>mongo.sample.php</code> instead. Copy your <code>mongo.php</code> somewhere safe <strong>before</strong> deploying, because <code>git checkout</code> removes it. After deploying, put it back, or create it again from the sample:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/config/mongo.sample.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/config/mongo.php</span></span></code></pre></div></div><p>These configuration files were removed and can be deleted if they are still on the server:</p><ul><li><code>semantic_search.php</code>: replaced by <code>nada_ai.php</code>. NADA-AI is set up under <strong>Site configurations → Search</strong>.</li><li><code>opensearch.php</code>: NADA&#39;s own OpenSearch search engine was removed. Sites that used it are switched to the database search engine by the migrations.</li></ul><h3 id="custom-themes" tabindex="-1">Custom themes <a class="header-anchor" href="#custom-themes" aria-label="Permalink to &quot;Custom themes&quot;">​</a></h3><p>If the site uses its own theme (a copy of <code>themes/nada52</code>), do not replace it with the stock theme. When upgrading from <strong>5.6</strong>, copy these new files from <code>themes/nada52/</code> into your theme, or catalog search fails:</p><table tabindex="0"><thead><tr><th>File</th><th>Why</th></tr></thead><tbody><tr><td><code>layout_vue.php</code></td><td>Page shell for catalog search</td></tr><tr><td><code>head_vue.php</code></td><td><code>&lt;head&gt;</code> for catalog search</td></tr><tr><td><code>css/catalog-vue-chrome.css</code></td><td>Fonts and colors for catalog search</td></tr><tr><td><code>css/fonts.css</code></td><td>Web fonts, moved out of <code>style.css</code></td></tr></tbody></table><p><code>layout_vue.php</code> includes your theme&#39;s <code>header.php</code> and <code>footer.php</code>, so your logo, menu and footer still appear. If your <code>head.php</code> comes from the 5.6 <code>nada52</code>, add the <code>fonts.css</code> stylesheet before <code>style.css</code>.</p><p>See <a href="/nada-documentation/installation-guide/configurations/customizing-themes.html">Customizing themes</a>.</p><h2 id="_2-run-the-database-migrations" tabindex="-1">2. Run the database migrations <a class="header-anchor" href="#_2-run-the-database-migrations" aria-label="Permalink to &quot;2. Run the database migrations&quot;">​</a></h2><p>Run the migrations <strong>before anyone logs in or uses the site</strong>. The new code expects the upgraded database, and login and the catalog fail until the migrations finish.</p><ol><li><p>Enable migrations in <code>application/config/migration.php</code>:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$config[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;migration_enabled&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> TRUE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></li><li><p>From the NADA folder (the one that contains <code>index.php</code>), run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli/migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> current</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # show the current version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli/migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list_migrations</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # list pending and applied migrations</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli/migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> latest</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # apply all pending migrations</span></span></code></pre></div></li><li><p>On production, set <code>migration_enabled</code> back to <code>FALSE</code>.</p></li></ol><div class="warning custom-block"><p class="custom-block-title">Use the command line</p><p>The command line is the recommended way to run the migrations. If it is not available, use <strong>Site administration → Database migration</strong> and run the pending migrations <strong>one at a time</strong> with <strong>Run</strong>. Do not use <strong>Migrate to latest</strong> for an upgrade: it runs everything in one web request, which can time out. See <a href="/nada-documentation/admin-guide/web-ui/database-migration.html">Database migration</a>.</p></div><h3 id="sql-server" tabindex="-1">SQL Server <a class="header-anchor" href="#sql-server" aria-label="Permalink to &quot;SQL Server&quot;">​</a></h3><ul><li>SQL Server needs <strong>Full-Text Search</strong> installed. The upgrade from 5.6 rebuilds the full-text index on the variables table.</li><li>On IIS, long migrations can exceed the FastCGI request limit in the web interface. Use the command line, or see the SQL Server notes in the NADA repository: <a href="https://github.com/ihsn/nada/blob/v5.8/install/NADA57_SQLSRV_UPGRADE.md" target="_blank" rel="noreferrer">SQL Server upgrade notes</a> and <a href="https://github.com/ihsn/nada/blob/v5.8/install/NADA57_SQLSRV_MANUAL_RUNBOOK.md" target="_blank" rel="noreferrer">manual runbook</a>.</li></ul><h2 id="_3-check-the-upgrade" tabindex="-1">3. Check the upgrade <a class="header-anchor" href="#_3-check-the-upgrade" aria-label="Permalink to &quot;3. Check the upgrade&quot;">​</a></h2><ol><li>Run <code>php index.php cli/migrate current</code>. The version should match the highest-numbered file in <code>application/migrations/</code>.</li><li>Log in as an administrator and open <strong>Site administration → Database migration</strong>. It shows the same version, with no pending migrations.</li><li>Open the catalog, a study page and an indicator page (if you have indicators).</li></ol><h2 id="_4-review-changes-that-may-affect-your-site" tabindex="-1">4. Review changes that may affect your site <a class="header-anchor" href="#_4-review-changes-that-may-affect-your-site" aria-label="Permalink to &quot;4. Review changes that may affect your site&quot;">​</a></h2><h3 id="solr" tabindex="-1">Solr <a class="header-anchor" href="#solr" aria-label="Permalink to &quot;Solr&quot;">​</a></h3><p>If the catalog uses Solr and you are upgrading from <strong>5.6</strong>, rebuild the Solr index after the migrations. The catalog search fields changed in 5.7, so an old index returns wrong or empty results. Update the schema and re-index the catalog as described in <a href="/nada-documentation/admin-guide/web-ui/solr.html">Solr search</a>. Catalog search is incomplete until indexing finishes.</p><h3 id="search-settings" tabindex="-1">Search settings <a class="header-anchor" href="#search-settings" aria-label="Permalink to &quot;Search settings&quot;">​</a></h3><p>The migrations rename the search settings, so there is nothing to change by hand.</p><table tabindex="0"><thead><tr><th>Old setting</th><th>New setting</th></tr></thead><tbody><tr><td><code>search_provider</code></td><td><code>search_engine</code>: <code>database</code>, <code>solr</code> or <code>nada_ai</code></td></tr><tr><td><code>semantic_search_url</code></td><td><code>nada_ai_url</code></td></tr><tr><td><code>semantic_search_api_key</code>, <code>semantic_search_admin_api_key</code></td><td><code>nada_ai_api_key</code></td></tr><tr><td><code>semantic_search_debug</code></td><td><code>nada_ai_debug</code></td></tr></tbody></table><h3 id="permissions-and-api-changes" tabindex="-1">Permissions and API changes <a class="header-anchor" href="#permissions-and-api-changes" aria-label="Permalink to &quot;Permissions and API changes&quot;">​</a></h3><ul><li><strong>Site and API logs:</strong> the Site logs, API logs and log clean-up pages use a new <strong>Site and API logs</strong> permission. Full administrators are not affected; grant it to other roles that need these pages.</li><li><strong>Filestore:</strong> each filestore action checks its own privilege of the <strong>Filestore</strong> permission (view, download, upload, delete). Roles that edit menu pages need <strong>view</strong> and <strong>upload</strong> for the image picker.</li><li><strong>API URLs moved:</strong> <code>api/db_logs</code>, <code>api/api_logs</code> and <code>api/filestore</code> are now under <code>api/admin/</code> (<code>api/admin/db_logs</code>, <code>api/admin/api_logs</code>, <code>api/admin/filestore</code>). Update any scripts that call the old URLs.</li><li><strong>API keys created before 5.6</strong> that were never converted are rejected. Users need to create a new key. To accept old keys for a while, set <code>$config[&#39;api_key_enable_legacy_support&#39;] = TRUE;</code> in <code>application/config/rest.php</code>.</li></ul><h3 id="indicators" tabindex="-1">Indicators <a class="header-anchor" href="#indicators" aria-label="Permalink to &quot;Indicators&quot;">​</a></h3><p>Indicators accept only the <strong>Open access</strong>, <strong>Direct access</strong> and <strong>Data not available</strong> data access types. Existing indicators keep their stored type, and the admin study page warns about any indicator whose type is no longer allowed.</p><h3 id="data-deposit" tabindex="-1">Data deposit <a class="header-anchor" href="#data-deposit" aria-label="Permalink to &quot;Data deposit&quot;">​</a></h3><p>The migrations create the new data deposit tables, but the feature stays off until you set <code>enable_datadeposit</code> to <code>true</code> in <code>application/config/datadeposit.php</code>. Projects created before 5.7 need to be imported into the new format; see <a href="https://github.com/ihsn/nada/blob/v5.8/install/DATADEPOSIT_MIGRATION.md" target="_blank" rel="noreferrer">Data deposit migration</a>.</p><h3 id="robots-txt" tabindex="-1">robots.txt <a class="header-anchor" href="#robots-txt" aria-label="Permalink to &quot;robots.txt&quot;">​</a></h3><p>Catalog search pages beyond the numbered pages use a cursor in the URL (<code>…&amp;cursor=…</code>). Stop crawlers from following them:</p><ul><li><p>If the web root has no <code>robots.txt</code>, copy NADA&#39;s <code>robots.txt.example</code> there as <code>robots.txt</code>.</p></li><li><p>If it already has one, add:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User-agent: *</span></span>
<span class="line"><span>Disallow: /*cursor=</span></span></code></pre></div></li></ul><p><code>robots.txt</code> must be at the root of the host. If NADA is installed in a subfolder, put it in the host&#39;s root folder.</p><h2 id="after-the-upgrade-new-components" tabindex="-1">After the upgrade: new components <a class="header-anchor" href="#after-the-upgrade-new-components" aria-label="Permalink to &quot;After the upgrade: new components&quot;">​</a></h2><p>These components are optional. Install the ones you need after NADA is upgraded:</p><table tabindex="0"><thead><tr><th>Component</th><th>Needed for</th><th>Guide</th></tr></thead><tbody><tr><td>MongoDB</td><td>Indicator (time series) data and the indicator data API</td><td><a href="/nada-documentation/installation-guide/installation-mongodb.html">MongoDB</a></td></tr><tr><td>NADA-AI</td><td>Semantic and multilingual search (NADA 5.8+)</td><td><a href="/nada-documentation/installation-guide/installation-nada-ai.html">NADA-AI</a>, then <a href="/nada-documentation/admin-guide/web-ui/nada-ai.html">NADA-AI search</a></td></tr><tr><td>MCP server</td><td>Connecting AI assistants to the catalog (NADA 5.8+)</td><td><a href="/nada-documentation/installation-guide/installation-mcp.html">MCP server</a></td></tr></tbody></table><h3 id="sites-already-running-nada-ai" tabindex="-1">Sites already running NADA-AI <a class="header-anchor" href="#sites-already-running-nada-ai" aria-label="Permalink to &quot;Sites already running NADA-AI&quot;">​</a></h3><p>If the site already uses NADA-AI, update NADA-AI first, then upgrade NADA and run the migrations. Afterwards:</p><ol><li>In <strong>Site configurations → Search</strong>, check the search engine, the NADA-AI URL and the API key, which must be NADA-AI&#39;s admin key.</li><li>Check that the NADA API key NADA-AI uses belongs to a full administrator, or to a user whose role has <strong>view</strong> and <strong>edit</strong> on the <strong>Search index</strong> permission. Without it, indexing stops with access denied.</li><li>On the <strong>Search index</strong> admin page, open <strong>Indexing</strong> and run <strong>Force re-index</strong> for each study type, so NADA-AI has the new filter fields.</li></ol><p>See the <a href="https://github.com/mah0001/nada-ai" target="_blank" rel="noreferrer">NADA-AI repository</a> for the NADA-AI side of the update.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Likely cause</th><th>Action</th></tr></thead><tbody><tr><td>Login fails with a 500 error</td><td>Migrations not run</td><td>Run <code>php index.php cli/migrate latest</code></td></tr><tr><td>Catalog search shows a division by zero error</td><td>Migrations not run</td><td>Run the migrations</td></tr><tr><td><code>/catalog</code> fails with a custom theme</td><td><code>layout_vue.php</code> missing from the theme</td><td>Copy the new theme files (<a href="#custom-themes">Custom themes</a>)</td></tr><tr><td>Indicator pages fail after upgrading from 5.6</td><td><code>mongo.php</code> removed by <code>git checkout</code></td><td>Restore it or create it from <code>mongo.sample.php</code></td></tr><tr><td>A migration fails part way</td><td>Partly applied</td><td>Fix the error and run <code>latest</code> again</td></tr><tr><td>Catalog search empty with Solr</td><td>Old Solr index</td><td>Rebuild the schema and re-index (<a href="#solr">Solr</a>)</td></tr></tbody></table><p>For more, see <a href="/nada-documentation/installation-guide/database-migrations-cli.html#troubleshooting">Database migrations (CLI) — troubleshooting</a>.</p><h2 id="what-s-new" tabindex="-1">What&#39;s new <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s new&quot;">​</a></h2><h3 id="_5-8" tabindex="-1">5.8 <a class="header-anchor" href="#_5-8" aria-label="Permalink to &quot;5.8&quot;">​</a></h3><ul><li>Home page redesigned around search, with the most viewed, featured and latest studies.</li><li>Site notices: a header bar and a pop-up notice.</li><li><strong>View PDF</strong> tab for document studies.</li><li>AI search through NADA-AI, and an MCP server for AI assistants.</li><li>Indicators: configurable default chart and table view; timeseries API documentation with a Swagger UI playground.</li><li>More admin pages moved to Vue 3.</li><li>Email configuration is now optional; PHP 8.4 compatibility fixes.</li></ul><h3 id="_5-7" tabindex="-1">5.7 <a class="header-anchor" href="#_5-7" aria-label="Permalink to &quot;5.7&quot;">​</a></h3><ul><li>Study pages rendered from JSON display templates, with a display template manager.</li><li>Built-in metadata editor uses the same templates as the Metadata Editor.</li><li>New data deposit interface and API.</li><li>Geospatial feature catalogue tab.</li><li>5.7.2: security hardening, consolidated migrations, SQL Server upgrade fixes.</li></ul><p>Full release notes are on <a href="https://github.com/ihsn/nada/releases" target="_blank" rel="noreferrer">GitHub</a>.</p>`,65)])])}const u=a(s,[["render",n]]);export{g as __pageData,u as default};
